@1 @ns Bench.Task02

export fn ParseDuration(String s) Int{
  var mut total=0
  var mut i=0
  while i<s.length{
    var numStart=i
    while i<s.length && s[i]>="0" && s[i]<="9"{i+=1}
    if i==numStart{return 0}
    var num=parseInt(s.slice(numStart, i))
    if i>=s.length{return 0}
    match s[i]{
      "h" total+=num*3600
      "m" total+=num*60
      "s" total+=num
      else return 0
    }
    i+=1
  }
  total
}
